    { id = 980, source = "wowhead-cata", lang = "en", family = "Bane of Agony", name = "Bane of Agony", desc = "Banes the target with agony, causing 1536 Shadow damage over 24 sec.  This damage is dealt slowly at first, and builds up as the Curse reaches its full duration.  Only one Bane per Warlock can be active on any one target.", expect = { total = 1536, school = 32, duration = 24, interval = 2 }, interval = 2, ignored = false, shaped = true, finisher = false, awarded = false },
    { id = 980, source = "wowhead-cata", lang = "de", family = "Bane of Agony", name = "Omen der Pein", desc = "Verflucht das Ziel mit Pein und verursacht im Verlauf von 24 Sek. 1536 Schattenschaden. Zunächst wird der Schaden langsam verursacht und er steigt an, bis das Omen seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Omen pro Hexenmeister auf einem beliebigen Ziel aktiv sein.", expect = { total = 1536, school = 32, duration = 24, interval = 2 }, interval = 2, ignored = false, shaped = true, finisher = false, awarded = false },
    { id = 603, source = "wowhead-cata", lang = "en", family = "Bane of Doom", name = "Bane of Doom", desc = "Banes the target with impending doom, causing 1948 Shadow damage every 15 sec.  When Bane of Doom deals damage, it has a 20% chance to summon a Demon guardian. \n\nOnly one target can have Bane of Doom at a time, only one Bane per Warlock can be active on any one target. Lasts for 1 min.", expect = false, interval = 3, ignored = false, shaped = false, finisher = false, awarded = false },
    { id = 603, source = "wowhead-cata", lang = "de", family = "Bane of Doom", name = "Omen der Verdammnis", desc = "Verflucht das Ziel mit drohender Verdammnis und verursacht alle 15 Sek. 1948 Schattenschaden. Wenn 'Omen der Verdammnis' Schaden verursacht, besteht eine Chance von 20%, dass ein Wächterdämon beschworen wird. Hält 1 Min. lang an.\n\nEs kann pro Hexenmeister nur jeweils ein Effekt von 'Omen der Verdammnis' gleichzeitig aktiv sein und pro Hexenmeister kann nur ein Omen auf einem Ziel gleichzeitig aktiv sein.", expect = false, interval = 3, ignored = false, shaped = false, finisher = false, awarded = false },
    { id = 348, source = "wowhead-cata", lang = "en", family = "Immolate", name = "Immolate", desc = "Burns the enemy for 1 Fire damage and then an additional 5 Fire damage over 15 sec. [Unstable Affliction: Only one Unstable Affliction or Immolate per Warlock can be active on any one target]", expect = { total = 5, school = 4, duration = 15, interval = 3 }, interval = 3, ignored = false, shaped = false, finisher = false, awarded = false },
    { id = 348, source = "wowhead-cata", lang = "de", family = "Immolate", name = "Feuerbrand", desc = "Verbrennt den Feind. Verursacht 1 Feuerschaden und fügt zusätzlich im Verlauf von 15 Sek. insgesamt 5 Feuerschaden zu. [Instabiles Gebrechen: Es kann pro Hexenmeister nur ein Effekt von 'Instabiles Gebrechen' oder 'Feuerbrand' auf einem Ziel gleichzeitig aktiv sein]", expect = { total = 5, school = 4, duration = 15, interval = 3 }, interval = 3, ignored = false, shaped = false, finisher = false, awarded = false },
