    { id = 44614, source = "wowhead-cata", lang = "en", family = "Frostfire Bolt", name = "Frostfire Bolt", desc = "Launches a bolt of frostfire at the enemy, causing 628 Frostfire damage and [Glyph of Frostfire: 19 additional damage over 9 sec, stacking up to 3 times / slowing the target by 40% for 9 sec].  This spell will be checked against the lower of the target's Frost and Fire resists.", expect = { total = 19, school = 1, duration = 9, interval = 3 }, interval = 3, ignored = false, shaped = false, finisher = false, awarded = false },
    { id = 44614, source = "wowhead-cata", lang = "de", family = "Frostfire Bolt", name = "Frostfeuerblitz", desc = "Schleudert einen Frostfeuerblitz auf den Feind, der sofort 628 Frostfeuerschaden verursacht [Glyphe 'Frostfeuer': sowie im Verlauf von 9 Sek. zusätzlich 19 Schaden. Dieser Effekt ist bis zu 3-mal stapelbar / und sein Bewegungstempo 9 Sek. lang um 40% verringert.] Der Schaden dieses Zaubers wird gegen den jeweils geringeren Frost- oder Feuerwiderstandswert des Ziels gerechnet.", expect = { total = 19, school = 1, duration = 9, interval = 3 }, interval = 3, ignored = false, shaped = false, finisher = false, awarded = false },
